<script setup lang="ts">
import { onMounted, ref } from 'vue'; import { useTemplateStore } from '../stores/templates'; import StatusBadge from '../components/StatusBadge.vue';
const store=useTemplateStore(); const source=ref<File|null>(null), name=ref('硬件测试过程检查单'), version=ref('A11')
onMounted(()=>{void store.loadTemplates().catch(()=>undefined)}); function pick(event:Event){source.value=(event.target as HTMLInputElement).files?.[0]??null}
async function upload(){if(!source.value)return; await store.upload({source:source.value,name:name.value,version:version.value}); source.value=null}
</script>
<template><section class="page-stack"><header class="page-header"><div><p class="eyebrow">模板规则管理</p><h1>审核模板</h1><p>上传模板后先审核校验项；仅已发布版本可用于新建审核任务。</p></div></header><div class="two-column template-layout"><form class="panel form-stack" @submit.prevent="upload"><h2>上传审核模板</h2><label><span>模板名称</span><input v-model="name" required></label><label><span>正式版本</span><input v-model="version" required></label><label><span>XLS 模板文件</span><input type="file" accept=".xls" required @change="pick"></label><button class="btn btn-primary" :disabled="!source || store.loading">上传并解析</button></form><article class="panel"><div class="panel-heading"><h2>模板版本</h2><span>{{ store.templates.length }} 个</span></div><div class="template-list"><RouterLink v-for="item in store.templates" :key="item.id" :to="`/templates/${item.id}`" class="template-item"><div><strong>{{ item.name }} · {{ item.version }}</strong><span>{{ item.effective_rules }} 个有效校验项 · {{ item.source_filename }}</span></div><StatusBadge :status="item.status"/></RouterLink><p v-if="!store.templates.length" class="empty-cell">暂无模板</p></div></article></div></section></template>
